"use strict";(self.webpackChunkreact_portfolio=self.webpackChunkreact_portfolio||[]).push([[621],{621:function(a){a.exports=JSON.parse('{"name":"Patriks Gudvins","menu":{"home":"S\u0101kums","about":"Par Mani","portfolio":"Portfelis","projects":"Viet\u0146u projekti","tiger":"T\u012b\u0123era valoda","portfolio_translator":"Portfe\u013ca tulkot\u0101js","formatter":"JSON un YAML format\u0113t\u0101js","contact":"Sazinieties ar mani"},"home":{"title":"Vec\u0101kais Full-Stack in\u017eenieris | Produkti un sist\u0113mas","animated":{"first":"Vec\u0101kais Full-Stack in\u017eenieris","second":"Sist\u0113mu un arhitekt\u016bras veidot\u0101js","third":"SaaS produktu in\u017eenieris","fourth":"Uzticama programmat\u016bra, biznesa rezult\u0101ti"},"footer":"Vietne tagad ir tulkota un pieejama vair\u0101k nek\u0101 100 valod\u0101s!","descriptionA":"Vec\u0101kais pilnu komplektu in\u017eenieris ar 6+ gadu pieredzi produktu p\u0101rveido\u0161an\u0101 no neskaidr\u0101m pras\u012bb\u0101m l\u012bdz uzticam\u0101m ra\u017eo\u0161anas sist\u0113m\u0101m. Es izstr\u0101d\u0101ju React, Angular, .NET, Node.js, Java, C#, Go un SQL lietojumprogrammu arhitekt\u016bru: skaidras pakalpojumu robe\u017eas, iztur\u012bgus datu mode\u013cus, dro\u0161us piek\u013cuves mode\u013cus un pieg\u0101des ce\u013ci, komandas var darboties ar p\u0101rliec\u012bbu.","descriptionB":"Mans darbs saista in\u017eeniertehniskos l\u0113mumus ar biznesa rezult\u0101tiem. S\u0101kot ar konstru\u0113\u0161anas apr\u0113\u0137inu SaaS, kas p\u0101rv\u0113r\u0161 izkl\u0101jlapu datus klientam sagatavotos priek\u0161likumos un beidzot ar ie\u0146\u0113mumus \u0123ener\u0113jo\u0161\u0101m t\u012bmek\u013ca platform\u0101m, es veidoju programmat\u016bru, \u0146emot v\u0113r\u0101 darbpl\u016bsmu, riskus un izm\u0113r\u0101ma v\u0113rt\u012bba, kas ir svar\u012bga cilv\u0113kiem, kuri to izmanto.","portfolio_button":"Mans Portfelis","contact_button":"Sazinieties ar mani","about_button":"Par Mani"},"about":{"title":"Par Mani","personal_summary":{"title":"Personiskais kopsavilkums","text":"Es esmu vec\u0101kais pilnas kaudzes in\u017eenieris, kas atrodas Orlando, FL un kuram pieder ce\u013c\u0161 no produkta probl\u0113mas l\u012bdz ra\u017eo\u0161anas rezult\u0101tam. Es veicu tehnolo\u0123iju izv\u0113li, lai izmantotu sist\u0113mu: .NET un Entity Framework Core, ja svar\u012bgs ir stingri struktur\u0113ts dom\u0113ns un p\u0101rbaud\u0101ma notur\u012bba; Le\u0146\u0137isks vai rea\u0123\u0113, ja ir sare\u017e\u0123\u012bti darbpl\u016bsm\u0101m ir nepiecie\u0161ams uztur\u0113jams interfeiss; Node.js vai Go, ja API, integr\u0101cijas vai augstas veiktsp\u0113jas r\u012bkam ir nepiecie\u0161ams koncentr\u0113ts izpildlaiks. Saist\u012bb\u0101 ar SaaS produktiem, iek\u0161\u0113j\u0101m darbpl\u016bsm\u0101m un platform\u0101m, kas v\u0113rstas uz klientiem, es pied\u0101v\u0101ju nep\u0101rprotamus kompromisus, dro\u0161u un elast\u012bgu dizainu, automatiz\u0113tu test\u0113\u0161anu un pieg\u0101des praksi, kas pal\u012bdz\u0113t komand\u0101m pieg\u0101d\u0101t v\u0113rt\u012bgu programmat\u016bru, neatst\u0101jot darb\u012bbas par\u0101dus."},"professional_experience":{"title":"Profesion\u0101l\u0101 pieredze","entries":[{"jobtitle":"Vec\u0101kais programmat\u016bras in\u017eenieris","where":"Interakt\u012bvs dizains","date":"2025.\xa0gads \u2013 tagadne"},{"jobtitle":"Programmat\u016bras in\u017eenieris","where":"Orion180 apdro\u0161in\u0101\u0161ana","date":"2024.\u20132025.\xa0gads"},{"jobtitle":"Programmat\u016bras in\u017eenieris","where":"SupremeMC","date":"2020.\u20132024.\xa0gads"},{"jobtitle":"Programmat\u016bras in\u017eenieris","where":"Pa\u0101trin\u0101t m\u0101c\u012b\u0161anos","date":"2023. gads"},{"jobtitle":"Vado\u0161ais programmat\u016bras in\u017eenieris (studentu programma)","where":"Klemsonas universit\u0101tes GDI programma","date":"2021.\u20132022.\xa0gads"},{"jobtitle":"Galda uzraugs","where":"Klemsona universit\u0101te","date":"2021.\u20132022.\xa0gads"}]},"technical_skills":{"title":"Tehnisk\u0101s prasmes","header1":"Programm\u0113\u0161anas valodas","header2":"Ietvari un bibliot\u0113kas","header3":"R\u012bki un tehnolo\u0123ijas"},"services":{"title":"Mani pakalpojumi","entries":[{"title":"Pilna kaudzes in\u017eenierija","text":"Es vadu produktu pieg\u0101di no gala l\u012bdz galam: p\u0101rv\u0113r\u0161u biznesa darbpl\u016bsmas sist\u0113mas robe\u017e\u0101s, datu mode\u013cos, API un saskarn\u0113s, p\u0113c tam veicu darbu, veicot test\u0113\u0161anu, izvieto\u0161anu, un iter\u0101cija. M\u0113r\u0137is ir programmat\u016bra, ko komanda var att\u012bst\u012bt un darbin\u0101t, nevis atvienotu ekr\u0101nu kolekcija."},{"title":"Produktu un platformu arhitekt\u016bra","text":"Es izv\u0113los platformas un mode\u013cus, pamatojoties uz probl\u0113mu: sl\u0101\u0146veida .NET pakalpojumi biznesa dom\u0113niem, komponentu vad\u012btas Angular vai React lietojumprogrammas sare\u017e\u0123\u012bt\u0101m darb\u012bb\u0101m, rel\u0101ciju datu mode\u013ci atbild\u012bg\u0101m darbpl\u016bsm\u0101m un integr\u0101cijas, kas izstr\u0101d\u0101tas, \u0146emot v\u0113r\u0101 atteices re\u017e\u012bmus, piek\u013cuves kontroli un apkopi."},{"title":"Ra\u017eo\u0161anai gatava pieg\u0101de","text":"Es veidoju, \u0146emot v\u0113r\u0101 realit\u0101ti p\u0113c palai\u0161anas: nosl\u0113pumi, kas tiek tur\u0113ti \u0101rpus avota kontroles, skaidri datu b\u0101zes migr\u0101cijas ce\u013ci, uz lomu balst\u012bta autoriz\u0101cija, valid\u0101cija pie sist\u0113mas robe\u017e\u0101m, automatiz\u0113ti testi, CI/CD izpratne un praktisk\u0101 nov\u0113rojam\u012bba. \u0160\u012bs ir deta\u013cas, kas prototipu p\u0101rv\u0113r\u0161 uzticam\u0101 programmat\u016br\u0101."}]}},"portfolio":{"title":"Portfelis","filter_by":"Filtr\u0113t portfeli p\u0113c:","entries":{"biblioteca":{"title":"Bibliot\u0113ka JSON","text":"Uz Python balst\u012bta lokaliz\u0101cijas konveijera, kas p\u0101rv\u0113r\u0161 vienu struktur\u0113ta satura avotu par glob\u0101li pieejamu portfeli. Tas apstr\u0101d\u0101 tulko\u0161anas datus k\u0101 apkopjamu sist\u0113mu, nevis manu\u0101li dubl\u0113tu lapas kopiju, \u013caujot vietnei m\u0113rogot vair\u0101k nek\u0101 100 valod\u0101s un padarot glob\u0101lu sasniedzam\u012bbu darb\u012bbas iesp\u0113jas vienreiz\u0113jas funkcijas viet\u0101.","link":"https://github.com/pattygcoding/Biblioteca-JSON"},"connect_four":{"title":"Savienojiet \u010detrus","text":"Milz\u012bga saime, kur\u0101 ir vair\u0101k nek\u0101 50\xa0sp\u0113les Connect Four implement\u0101cijas. \u0160is projekts ietver implement\u0101cijas vair\u0101k nek\u0101 30 da\u017e\u0101d\u0101s programm\u0113\u0161anas valod\u0101s, tostarp Java, C++, Python, JavaScript un cit\u0101s. Turkl\u0101t taj\u0101 ir iek\u013cauti ar\u012b vair\u0101k nek\u0101 20\xa0da\u017e\u0101di ietvari vai citi form\u0101ti, tostarp React.js, Ruby on Rails, ASP.NET un citi.","link":"https://github.com/pattygcoding/Connect-Four-Language-Tree"},"grocery_app":{"title":"P\u0101rtikas pre\u010du lietotne","text":"Pilna steka .NET 9 Blazor Server lietojumprogramma, kas demonstr\u0113 apzin\u0101tu aizmugursist\u0113mas arhitekt\u016bru biznesa darbpl\u016bsmai. Kontrolieris/pakalpojums/repozitorijs sadala lietojumprogrammas noteikumus, piek\u013cuvi datiem un prezent\u0101ciju neatkar\u012bgi p\u0101rbaud\u0101mas; Entity Framework Core nodro\u0161ina ilgsto\u0161u notur\u012bbu; un visaptvero\u0161s testu komplekts aizsarg\u0101 uzved\u012bbu produktam att\u012bstoties.","link":"https://github.com/pattygcoding/Grocery-App-Blazor"},"interop":{"title":"Interop projekts","text":"Vair\u0101ku valodu savietojam\u012bbas atsauce, kas aptver 15 programm\u0113\u0161anas valodas un 18 izpildes mode\u013cus. Projekts p\u0113ta robe\u017eas, kur sist\u0113mas bie\u017ei k\u013c\u016bst trauslas: procesu l\u012bgumi, datu apmai\u0146a, izpildlaika uzved\u012bba un atk\u0101rtojami integr\u0101cijas ce\u013ci. Tas atspogu\u013co sist\u0113mas dom\u0101\u0161anu, kas nepiecie\u0161ama, ja produkts ir liel\u0101ks par vienu kaudz\u012bti.","link":"https://github.com/pattygcoding/Interop-Samples"},"inventory_register":{"title":"Invent\u0101ra re\u0123istrs","text":"Pilna POS un kr\u0101jumu darbpl\u016bsma, kas izveidota, izmantojot Angular\xa017+ un Node.js. Tas model\u0113 B2B sist\u0113mas darb\u012bbas probl\u0113mas: autentific\u0113ti lietot\u0101ji, uz lom\u0101m balst\u012bta piek\u013cuves kontrole, kr\u0101jumu precizit\u0101te un viltota maks\u0101jumu pl\u016bsma. Projekts ir izstr\u0101d\u0101ts, \u0146emot v\u0113r\u0101 faktisko darbu, ko veic re\u0123istra komanda, nevis tikai ietvara l\u012bdzek\u013cu katalogu.","link":"https://github.com/pattygcoding/Restaurant-Inventory-Register"},"formatter":{"title":"JSON un YAML autom\u0101tiskais format\u0113t\u0101js","text":"Uz p\u0101rl\u016bkprogrammu balst\u012bts JSON un YAML valid\u0101cijas un format\u0113\u0161anas r\u012bks, kas ieb\u016bv\u0113ts Go un kompil\u0113ts WebAssembly. P\u0101rvietojot pars\u0113\u0161anas programmu uz WASM, mijiedarb\u012bba tiek saglab\u0101ta atsauc\u012bga un lok\u0101la p\u0101rl\u016bkprogrammai, vienlaikus izmantojot \u012bstu pars\u0113t\u0101ju, lai uztvertu neder\u012bgu ievadi. Tas ir m\u0113r\u0137tiec\u012bgs piem\u0113rs izpildlaika arhitekt\u016bras izv\u0113lei veiktsp\u0113jai, p\u0101rnesam\u012bbai un lietot\u0101ju uztic\u012bbai.","link":"https://github.com/pattygcoding/JSON-YAML-Auto-Formatter"},"takeoff_engine":{"title":"Pacel\u0161an\u0101s dzin\u0113js","text":"Konstrukcija, kur\u0101 tiek nov\u0113rt\u0113ta SaaS, pamatojoties uz d\u0101rgu darbuz\u0146\u0113m\u0113ja darbpl\u016bsmu, kur\u0101 var rasties k\u013c\u016bdas. Produkts React + Express uz\u0146em CSV un Excel datus, kart\u0113 nekonsekventas kolonnas izmantojam\u0101 dom\u0113na model\u012b, apr\u0113\u0137ina tran\u0161eju rak\u0161anas un zemes darbu apjomus, izseko darbu un mar\u0137\u0113jumu un izstr\u0101d\u0101 klientam gatavus PDF un Word priek\u0161likumus. T\u0101 ir pilna produkta dz\u012bves cikla in\u017eenierija: datu pars\u0113\u0161ana, apr\u0113\u0137inu noteikumi, uzlabota operatora darbpl\u016bsma un rezult\u0101ti, kas pal\u012bdz uz\u0146\u0113mumam p\u0101riet no neapstr\u0101d\u0101tas ievades uz cenu.","link":"https://github.com/pattygcoding/takeoff-engine"},"minecraft_json_generator":{"title":"Minecraft JSON \u0123enerators","text":"Viegls JSON \u0123enerators, kas ieb\u016bv\u0113ts Python Minecraft resursu un datu pakotn\u0113m. \u0160is projekts tiek izmantots, lai \u0123ener\u0113tu JSON failus Minecraft modifik\u0101cij\u0101m, tostarp piel\u0101gotiem vienumiem, blokiem un ent\u012btij\u0101m. \u013boti noder\u012bga ne tikai piel\u0101gotu datu pakot\u0146u izveidei, bet ar\u012b modifik\u0101cij\u0101m, izmantojot modu\u013cu nosaukuma mai\u0146as funkciju.","link":"https://github.com/pattygcoding/Minecraft-JSON-Generator"},"educational_experience":{"title":"Mana izgl\u012bt\u012bbas pieredze","text":"Paral\u0113li saviem person\u012bgajiem projektiem esmu apguvis ar\u012b daudzas prasmes no izgl\u012bt\u012bbas pieredzes. Noklik\u0161\u0137iniet \u0161eit, lai skat\u012btu manu LinkedIn profilu, lai ieg\u016btu vair\u0101k inform\u0101cijas.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"professional_experience":{"title":"Mana profesion\u0101l\u0101 pieredze","text":"Vair\u0101k nek\u0101 se\u0161us gadus ilga profesion\u0101la in\u017eenierzin\u0101t\u0146u pieredze produktu komand\u0101s, biznesa platform\u0101s un klientiem paredz\u0113taj\u0101 programmat\u016br\u0101. Mans darbs ir ietv\u0113ris apkopjamu lietojumprogrammu sl\u0101\u0146u izveidi, sadarb\u012bbu da\u017e\u0101d\u0101s pieg\u0101des discipl\u012bn\u0101s un tehnisku l\u0113mumu pie\u0146em\u0161anu saist\u012bb\u0101 ar produkta dz\u012bves ciklu. risku un ilgtermi\u0146a \u012bpa\u0161umties\u012bbas.","link":"https://www.linkedin.com/in/patrickgoodwin7"},"portfolio_website":{"title":"Patrika Gudvina portfe\u013ca vietne","text":"Uz ra\u017eo\u0161anu v\u0113rsts React portfelis, kur\u0101 pieejam\u012bba un glob\u0101l\u0101 sasniedzam\u012bba tiek uzskat\u012bta par in\u017eeniertehnisk\u0101m pras\u012bb\u0101m. Tas ietver uztur\u0113jamu tulko\u0161anas cauru\u013cvadu vair\u0101k nek\u0101 100 valod\u0101m, interakt\u012bvus r\u012bkus, ko nodro\u0161ina WebAssembly, atsauc\u012bgus un pieejamus lietot\u0101ja interfeisa mode\u013cus un projekta arhitekt\u016bru. paredz\u0113ts aug\u0161anai, kad tiek nos\u016bt\u012bts jauns darbs.","link":"https://www.pattygcoding.com"},"lua_library":{"title":"Patrika Lua skriptu bibliot\u0113ka","text":"Noder\u012bga Lua skriptu bibliot\u0113ka turpm\u0101kai uzzi\u0146ai. \u0160\u012b bibliot\u0113ka tiek izmantota, lai automatiz\u0113tu uzdevumus Lua skriptos, kas var b\u016bt noder\u012bgi uzdevumiem, kuriem nepiecie\u0161ama veiktsp\u0113ja, jo Lua parasti ir \u0101tr\u0101ka skriptu valoda nek\u0101 Python un Ruby.","link":"https://github.com/pattygcoding/Lua-Scripts"},"excel_scripts":{"title":"Patrika Microsoft Excel izkl\u0101jlapu skripti (VBA)","text":"Noder\u012bga VBA skriptu bibliot\u0113ka programmai Microsoft Excel. \u0160\u012b bibliot\u0113ka tiek izmantota, lai automatiz\u0113tu uzdevumus Excel izkl\u0101jlap\u0101s.","link":"https://github.com/pattygcoding/Spreadsheet-Scripts"},"neovim_config":{"title":"Patrika Neovim konfigur\u0101cija","text":"Mana person\u012bg\u0101 Neovim konfigur\u0101cija. \u0160is projekts tiek izmantots, lai konfigur\u0113tu Neovim p\u0113c man\u0101m v\u0113lm\u0113m, tostarp piel\u0101gotus tausti\u0146savienojumus, mot\u012bvus un spraud\u0146us. \u0160is projekts tiek izmantots, lai padar\u012btu Neovim lietot\u0101jam draudz\u012bg\u0101ku un efekt\u012bv\u0101ku manai person\u012bgai lieto\u0161anai.","link":"https://github.com/pattygcoding/Neovim-Config"},"python_maps":{"title":"Patrika kar\u0161u \u0123enerators","text":"Python \u0123eotelpisk\u0101s atskaites r\u012bks, kas izveidots ar GeoPandas un Matplotlib, lai \u0123ener\u0113tu ASV apgabalu un \u0161tatu kartes. Tas p\u0101rv\u0113r\u0161 \u0123eogr\u0101fiskos datus par las\u0101miem anal\u012bzes artefaktiem, demonstr\u0113jot datu pl\u016bsmas dom\u0101\u0161anas veidu: atlasiet pareiz\u0101s dom\u0113na bibliot\u0113kas, normaliz\u0113jiet ievades un izveidojiet izvades, kas atbalst\u012bt skaidrus l\u0113mumus.","link":"https://i.imgur.com/HxYLSXC.png"},"powershell_library":{"title":"Patrika PowerShell skriptu bibliot\u0113ka","text":"Noder\u012bga PowerShell skriptu bibliot\u0113ka turpm\u0101kai uzzi\u0146ai. Noder\u012bgs ar $profile skripta funkciju, jo es uzskatu, ka tas ir \u013coti noder\u012bgs uzdevumu automatiz\u0113\u0161anai no Windows termin\u0101\u013ca, jo esmu bie\u017es Windows OS lietot\u0101js.","link":"https://github.com/pattygcoding/Powershell-Scripts"},"ruby_library":{"title":"Patrika Rub\u012bna skriptu bibliot\u0113ka","text":"Noder\u012bga Ruby skriptu bibliot\u0113ka turpm\u0101kai uzzi\u0146ai. Noder\u012bgs n\u0101kotnes Ruby on Rails att\u012bst\u012bbas koncepcij\u0101m.","link":"https://github.com/pattygcoding/Ruby-Scripts"},"pdf_builder":{"title":"PDF prasmju veidot\u0101js","text":"Dokumentu \u0123ener\u0113\u0161anas darbpl\u016bsma, kas izveidota, izmantojot Python, Pdfkit, Jinja2, HTML un struktur\u0113tus JSON datus. Tas atdala atk\u0101rtoti lietojamus datus no prezent\u0101ciju veidn\u0113m, lai konsekventi \u0123ener\u0113tu piel\u0101gotus PDF CV, kas ir praktisks modelis manu\u0101la darba samazin\u0101\u0161anai un biznesa dokumentu veido\u0161anai. atk\u0101rtojams.","link":"https://github.com/pattygcoding/PDFBuilderPublic"},"rijandel_encryption":{"title":"Rijandel \u0161ifr\u0113\u0161anas projekts","text":"10+ Rijndael implement\u0101ciju sal\u012bdzino\u0161a kopa 128, 192 un 256 bitu variantos. Dro\u0161\u012bbas zi\u0146\u0101 jut\u012bga algoritma atk\u0101rtota ievie\u0161ana da\u017e\u0101d\u0101s valod\u0101s ir disciplin\u0113ts vingrin\u0101jums prec\u012bz\u0101m specifik\u0101cij\u0101m, p\u0101rbaud\u0101mai uzved\u012bbai un valodas l\u012bme\u0146a p\u0101rnesam\u012bbas ierobe\u017eojumiem, visi noder\u012bgie instinkti sist\u0113m\u0101m, kas apstr\u0101d\u0101 sensit\u012bvus datus.","link":"https://github.com/pattygcoding/SupremeMC"},"suprememc":{"title":"SupremeMC Minecraft Mod","text":"Minecraft Mod, kas sp\u0113lei pievieno piel\u0101gotus r\u012bkus, bru\u0146as, mobus, blokus, izm\u0113rus un daudzas citas funkcijas. Izstr\u0101d\u0101ts ar Java versij\u0101m 8\u201317 atsevi\u0161\u0137\u0101m Minecraft versij\u0101m no 1.16 l\u012bdz 1.20.","link":"https://www.curseforge.com/minecraft/mc-mods/suprememc"},"tiger_programming_language":{"title":"T\u012b\u0123era programm\u0113\u0161anas valoda","text":"Programm\u0101 Go ieb\u016bv\u0113ta piel\u0101gota programm\u0113\u0161anas valoda un tulks, lai izp\u0113t\u012btu valodas izpildlaika dizainu, izpildes uzved\u012bbu un veiktsp\u0113jas kompromisus. Kompil\u0113jot to WebAssembly un integr\u0113jot to portfel\u012b, tiek izveidota re\u0101la, p\u0101rbaud\u0101ma produkta virsma sist\u0113mu l\u012bme\u0146a in\u017eenierijai, nevis atst\u0101ta darbu k\u0101 tikai repozitorija eksperiments.","link":"https://www.pattygcoding.com/tiger"},"tiger_tailgating_pros":{"title":"Tiger Tailgating Pros vietne","text":"React vietne, kas pieg\u0101d\u0101ta Clemson, SC bag\u0101\u017eas nodal\u012bjuma ier\u012bko\u0161anas uz\u0146\u0113mumam. \u0160is darbs p\u0101rv\u0113r\u0161 maz\u0101 uz\u0146\u0113muma pied\u0101v\u0101jumu skaidr\u0101 klientu ce\u013cojum\u0101 un uzticam\u0101 t\u012bmek\u013ca kl\u0101tb\u016btne, izmantojot produktu dom\u0101\u0161anu, lai pal\u012bdz\u0113tu re\u0101lai organiz\u0101cijai p\u0101rv\u0113rst interesi. uzzi\u0146\u0101m un ie\u0146\u0113mumiem.","link":"https://github.com/pattygcoding/TTProsBeta"},"turing_machine":{"title":"Tj\u016bringa ma\u0161\u012bnas projekts","text":"\u0122imene, kur\u0101 ir vair\u0101k nek\u0101 30\xa0Tj\u016bringa ma\u0161\u012bnas implement\u0101ciju. Izmanto, lai demonstr\u0113tu da\u017e\u0101du programm\u0113\u0161anas valodu, \u012bpa\u0161i t\u012b\u0123era programm\u0113\u0161anas valodu, piln\u012bgumu p\u0113tniec\u012bbai.","link":"https://github.com/pattygcoding/Turing-Machines"}}},"tiger_programming_language":{"title":"T\u012b\u0123era programm\u0113\u0161anas valoda"},"contact":{"title":"Sazinieties ar mani","header":"Kontaktinform\u0101cija","email":"pattygsocials@gmail.com","description":"Es atbildu uz jaut\u0101jumiem no e-pasta un LinkedIn zi\u0146ojumiem. Es ar\u012b atzvan\u012b\u0161u, ja mans numurs tiks sniegts, izmantojot CV vai cit\u0101di, lai gan es grib\u0113tu, lai mans t\u0101lru\u0146a numurs b\u016btu priv\u0101ts."},"formatter":{"title":"JSON un YAML Linter","description":"Uz p\u0101rl\u016bkprogrammu balst\u012bts datu kvalit\u0101tes r\u012bks, kas valid\u0113 un format\u0113 JSON un YAML, izmantojot Go dzin\u0113ju, kas kompil\u0113ts WebAssembly. Arhitekt\u016bra turpina analiz\u0113t lietot\u0101ja tuvum\u0101, lai nodro\u0161in\u0101tu \u0101tru, priv\u0101tu atgriezenisko saiti, vienlaikus ievie\u0161ot re\u0101lus sintakses noteikumus datu robe\u017e\u0101s. Tas ir kompakts piem\u0113rs uzticamas izstr\u0101d\u0101t\u0101ja darbpl\u016bsmas izveidei, \u0146emot v\u0113r\u0101 pareiz\u012bbu, veiktsp\u0113ju un uzticam\u012bbu.","more_info1":"Lai ieg\u016btu papildinform\u0101ciju, skatiet README sada\u013c\u0101","more_info2":"JSON/YAML format\u0113\u0161anas repozitorijs.","format_as":"Format\u0113t k\u0101:","auto_detect":"Autom\u0101tisk\u0101 noteik\u0161ana","format":"Lint & Format","valid_json":"\u2713 Der\u012bgs JSON","valid_yaml":"\u2713 Der\u012bgs YAML","invalid_json":"Neder\u012bgs JSON","invalid_yaml":"Neder\u012bgs YAML","empty_input":"L\u016bdzu, ievadiet k\u0101du JSON vai YAML, lai izvilktu.","too_large":"P\u0101r\u0101k liela ievade (at\u013cauts ne vair\u0101k k\u0101 1\xa0MB).","fixed_yaml_spacing":"\u26a0 YAML bija neder\u012bga atstarpe/atk\u0101pe, ta\u010du t\u0101 ir autom\u0101tiski labota un format\u0113ta.","loading":"Notiek format\u0113t\u0101ja iel\u0101de...","waiting_for_input":"Gaida ievadi...","load_failed":"Nevar iel\u0101d\u0113t format\u0113t\u0101ju.","output":"Izvade:","input_code":"Ievade","json_examples":"JSON piem\u0113ri","yaml_examples":"YAML piem\u0113ri"},"tiger":{"title":"T\u012b\u0123era valoda","description":"Tiger ir piel\u0101gota programm\u0113\u0161anas valoda un Go tulks, kas izstr\u0101d\u0101ts, lai izp\u0113t\u012btu izpildlaika arhitekt\u016bru, valodas semantiku un veiktsp\u0113jas kompromisus. Tulka kompil\u0113\u0161ana WebAssembly p\u0101rv\u0113r\u0161 sist\u0113mu darb\u012bbu par interakt\u012bvu, uz p\u0101rl\u016bkprogrammu balst\u012btu produktu: lietot\u0101ji var tie\u0161i izpild\u012bt programmas, kam\u0113r izpildlaiks paliek p\u0101rn\u0113s\u0101jams. un izol\u0113ts no resursdatora lietojumprogrammas.","more_info1":"Lai ieg\u016btu papildinform\u0101ciju, skatiet README sada\u013c\u0101","more_info2":"Tiger programm\u0113\u0161anas valodas GitHub kr\u0101tuve.","select_engine":"Izv\u0113lieties dzin\u0113ju:","tiger_code":"T\u012b\u0123era kods:","run_tiger":"Palaist T\u012b\u0123eri","output":"Izvade:"},"tab":{"title":"Patriks Gudvins","description":"Vec\u0101kais pilnas komplekta in\u017eenieris ar 6+\xa0gadu pieredzi SaaS produktu, ra\u017eo\u0161anas sist\u0113mu un ie\u0146\u0113mumus \u0123ener\u0113jo\u0161as programmat\u016bras projekt\u0113\u0161an\u0101."},"copy":{"text":"Kop\u0113t","copied":"Kop\u0113ts!"},"social_media":{"github":"GitHub","linkedin":"LinkedIn","youtube":"YouTube","text_strip":"Sekojiet man"},"languages":{"title":"Portfe\u013ca tulkot\u0101js","description":"Uzziniet, k\u0101 mans portfolio ir pieejams apmekl\u0113t\u0101jiem no visas pasaules, izmantojot atbalstu vair\u0101k nek\u0101 100 valod\u0101s.","global_accessibility":{"title":"Glob\u0101l\u0101 pieejam\u012bba","description":"Mans portfolio ir pieejams vair\u0101k nek\u0101 {count} valod\u0101s, padarot to pieejamu apmekl\u0113t\u0101jiem no visas pasaules. \u0160\u012b daudzvalodu pieeja par\u0101da manu ap\u0146em\u0161anos nodro\u0161in\u0101t iek\u013cau\u0161anu un glob\u0101lo sasniedzam\u012bbu programmat\u016bras izstr\u0101d\u0113.","stats":{"languages_supported":"Atbalst\u012bt\u0101s valodas","countries_represented":"P\u0101rst\u0101v\u0113t\u0101s valstis","continents_covered":"Aptvertie kontinenti"}},"features":{"title":"Funkcijas","items":[{"title":"Tulko\u0161ana re\u0101llaik\u0101:","description":"Nekav\u0113joties p\u0101rsl\u0113dziet valodas, izmantojot valodas atlas\u012bt\u0101ju"},{"title":"Uz URL balst\u012bta valoda:","description":"Valodas preferences tiek saglab\u0101tas URL"},{"title":"Viet\u0113j\u0101 skripta atbalsts:","description":"Pareiza t\u0101du skriptu k\u0101 ar\u0101bu, \u0137\u012bnie\u0161u, hindi un citu skriptu render\u0113\u0161ana"},{"title":"Kult\u016bras jut\u012bgums:","description":"Tulkojumos tiek \u0146emts v\u0113r\u0101 kult\u016bras konteksts, nevis tikai burtiskas noz\u012bmes"},{"title":"SEO optimiz\u0113ts:","description":"Katrs valodas variants ir optimiz\u0113ts mekl\u0113t\u0101jprogramm\u0101m"}]},"world_map":{"title":"Interakt\u012bv\u0101 pasaules karte","description":"Virziet kursoru virs valst\u012bm kart\u0113, lai redz\u0113tu to atbalst\u012bt\u0101s valodas:","languages_label":"Valodas","legend":{"supported":"Atbalst\u012bt\u0101s valodas","not_supported":"Nav valodas atbalsta"},"zoom_controls":{"zoom_in":"Pietuvin\u0101t","zoom_out":"T\u0101lin\u0101t","reset":"Atiestat\u012bt skatu"}},"supported_languages":{"title":"Atbalst\u012bt\u0101s valodas"},"interactive_country_map":{"title":"Interakt\u012bv\u0101 valsts karte","description":"Virziet kursoru virs t\u0101l\u0101k nor\u0101d\u012btaj\u0101m valst\u012bm, lai skat\u012btu to atbalst\u012bt\u0101s valodas.","language_count":{"single":"valodu","multiple":"valodas"}},"tooltips":{"no_language_support":"Nav valodas atbalsta"}},"logotext":"PATRIKS"}')}}]);